import {normalizeMeetingEdit} from './core.mjs';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const normalizeHeader=s=>String(s||'').toLowerCase().normalize('NFKC').replace(/[\s_\-(),.:/]+/g,'');
function splitLine(line,delimiter){const cells=[];let value='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(quoted&&line[i+1]==='"'){value+='"';i++}else quoted=!quoted}else if(c===delimiter&&!quoted){cells.push(value.trim());value=''}else value+=c}cells.push(value.trim());return cells}
function parseTable(input){
 const text=String(input||'').replace(/^\uFEFF/,'').trim();if(!text)throw Error('Paste the spreadsheet rows first.');if(text.length>300000)throw Error('Use text smaller than 300 KB.');
 const lines=text.split(/\r?\n/).filter(line=>line.trim()),first=lines[0],delimiter=first.includes('|')?'|':first.includes('\t')?'\t':',';
 const parsed=lines.map(line=>{let cells=splitLine(line,delimiter);if(delimiter==='|'&&cells[0]==='')cells.shift();if(delimiter==='|'&&cells.at(-1)==='')cells.pop();return cells});
 const filtered=parsed.filter(row=>!row.every(v=>/^:?-+:?$/.test(v))),headers=filtered.shift().map(normalizeHeader);
 const find=names=>headers.findIndex(h=>names.some(n=>h===n||h.startsWith(n)));
 const ix={topic:find(['ማኅበራት','ማህበራት','topic','mahber','name']),date:find(['የጉባኤቀን','date','meetingdate']),teacher:find(['መምህር','teacher','teachername']),zoomLink:find(['zoomlink','link','joinlink']),startTime:find(['starttime','time']),durationMinutes:find(['durationminutes','duration']),canva:find(['poster','posterurl','canva','canvalink','designlink'])};
 if(ix.zoomLink<0)throw Error('A Zoom Link column is required to match existing meetings.');
 return filtered.map((cells,i)=>{const get=k=>ix[k]>=0?(cells[ix[k]]||'').trim():'';const raw=get('date');let date='';if(raw){const m=raw.match(/\b(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\.?\s+(\d{1,2})(?:,?\s+(\d{4}))?\b/i);if(m){const month=['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'].indexOf(m[1].slice(0,3).toLowerCase())+1;date=String(Number(m[3]||2026)).padStart(4,'0')+'-'+String(month).padStart(2,'0')+'-'+m[2].padStart(2,'0')}else if(/^\d{4}-\d{2}-\d{2}$/.test(raw))date=raw;else throw Error('Row '+(i+2)+': date must include an English month/day (e.g. Nov 14) or YYYY-MM-DD.')}
  const startTime=get('startTime');if(startTime&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(startTime))throw Error('Row '+(i+2)+': startTime must use 24-hour HH:MM.');
  const durationMinutes=get('durationMinutes');if(durationMinutes&&!/^\d+$/.test(durationMinutes))throw Error('Row '+(i+2)+': durationMinutes must be a whole number.');
  return{rowNumber:i+2,topic:get('topic'),date,teacher:get('teacher'),zoomLink:get('zoomLink'),startTime,durationMinutes,canva:get('canva')};
 });
}
async function api(path,body){if(typeof window.gubaeBulkRequest!=='function')throw Error('Sign in and wait for the shared workspace to finish loading.');return window.gubaeBulkRequest(path,body)}
function init(){const bar=$('#programBar');if(!bar||$('#bulkMeetingImport'))return;const button=document.createElement('button');button.id='bulkMeetingImport';button.className='secondary';button.textContent='Update existing meetings';bar.append(button);button.onclick=openImporter}
function openImporter(){
 let dialog=$('#bulkMeetingDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='bulkMeetingDialog';dialog.innerHTML='<div class="dialog-top"><strong>Update existing meetings</strong><button class="icon-button" id="bulkClose" aria-label="Close">×</button></div><div class="form-stack"><p>Paste the spreadsheet with its header row. Rows are matched to existing meetings by the Zoom meeting ID. No meetings are created.</p><p class="notice">Blank cells are preserved. Canva links are saved in the Canva field, not as poster image files. Existing reports and sent confirmations are preserved.</p><label class="field">Spreadsheet data<textarea id="bulkMeetingText" rows="11" maxlength="300000" placeholder="ማኅበራት | የጉባኤ ቀን | መምህር | Zoom Link | startTime | durationMinutes | poster"></textarea></label><div class="button-row"><button class="primary" id="bulkPreview">Preview changes</button><button class="secondary" id="bulkTemplate">Download CSV template</button></div><div id="bulkResults" aria-live="polite"></div><button class="primary" id="bulkApply" disabled>Confirm and update matched meetings</button><p id="bulkError" role="alert"></p></div>';document.body.append(dialog);$('#bulkClose').onclick=()=>dialog.close();$('#bulkTemplate').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['ማኅበራት,የጉባኤ ቀን,መምህር,Zoom Link,startTime (24-hour Dubai time),durationMinutes,poster (Canva URL)\r\n'],{type:'text/csv;charset=utf-8'}));a.download='gubae-existing-meetings-template.csv';a.click();URL.revokeObjectURL(a.href)};$('#bulkPreview').onclick=preview;$('#bulkApply').onclick=apply}
 dialog.showModal();
}
let reviewed=null;
async function preview(){
 const results=$('#bulkResults'),error=$('#bulkError'),save=$('#bulkApply');reviewed=null;save.disabled=true;error.textContent='';results.textContent='Checking existing meetings…';
 try{const rows=parseTable($('#bulkMeetingText').value),prepared=await api('/api/meetings/bulk-preview',{rows});reviewed={rows,prepared};const updates=prepared.updates||[];
  results.innerHTML='<p><strong>'+updates.length+' existing meetings ready to update</strong> · '+(prepared.unmatched||[]).length+' unmatched · '+(prepared.duplicates||[]).length+' duplicate IDs · '+(prepared.invalid||[]).length+' invalid rows</p><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Mahber</th><th>Zoom ID</th><th>Proposed changes</th></tr></thead><tbody>'+updates.map(u=>'<tr><td>'+esc(u.topic)+'</td><td>'+esc(u.zoomId)+'</td><td>'+Object.entries(u.patch).filter(([k])=>k!=='teacherId').map(([k,v])=>'<small>'+esc(k)+': '+esc(v)+'</small>').join('')+(u.warnings||[]).map(w=>'<small>'+esc(w)+'</small>').join('')+'</td></tr>').join('')+'</tbody></table></div>'+['unmatched','duplicates','invalid'].map(k=>(prepared[k]||[]).length?'<h4>'+k+'</h4><ul>'+prepared[k].map(v=>'<li>'+esc(JSON.stringify(v))+'</li>').join('')+'</ul>':'').join('');
  save.disabled=!updates.length;
 }catch(e){error.textContent=e.message;results.textContent=''}
}
async function apply(){if(!reviewed?.rows?.length)return;const save=$('#bulkApply'),error=$('#bulkError');save.disabled=true;error.textContent='';try{const result=await api('/api/meetings/bulk-update',{rows:reviewed.rows});$('#bulkResults').insertAdjacentHTML('afterbegin','<p class="notice">Saved '+result.updated+' meeting updates. Reloading the workspace…</p>');setTimeout(()=>location.reload(),500)}catch(e){error.textContent=e.message+' Refresh and preview again before retrying.';save.disabled=false}}
const observer=new MutationObserver(init);observer.observe(document.documentElement,{childList:true,subtree:true});document.addEventListener('DOMContentLoaded',init);init();
